\label{nat part}
Given a partition $\mathcal{V}$ of the time-$s$ configuration $U_s$, the natural partitioning $(\mathcal{U}_t)_{t \geq s}$ of $(U_t)_{t \geq s}$ with $\mathcal{V}$ is inductively defined by $\mathcal{U}_s = \mathcal{V}$ and  
\begin{equation}\label{c with u}
\mathcal{U}_{t+1} = \left( \mathcal{U}_t \sd{i_t} \{X_t\} \right) \cup^{i_t} \{Y_t\}, \quad t \geq s,
\end{equation}
in terms of the time-$t$ sites of activation $X_t$ and transport $Y_t$, and the part $i_t = [X_t]_{\mathcal{U}_t}$ of $\mathcal{U}_t$ to which $X_t$ belongs.

\label{clustering def}
For $a, b > 0$, a partition $\mathcal{V} = (\mathcal{V}^1, \dots, \mathcal{V}^k)$ of a configuration $V$ is an $(a,b)$ clustering of $V$, denoted $\mathcal{V} \in \mathrm{Clust}_{a,b} (V)$, if
\begin{equation}\label{abs rel sep}
|\mathcal{V}^i| \geq 2, \quad \mathrm{dist} (\mathcal{V}^i, \mathcal{V}^{\neq i}) \geq a, \quad \text{and} \quad \mathrm{diam} (\mathcal{V}^i) \leq b \log \mathrm{dist} (\mathcal{V}^i, \mathcal{V}^{\neq i}), \quad 1 \leq i \leq k.
\end{equation}
We refer to the parts of a clustering as clusters. In particular, we call $\mathcal{V}^i$ a dimer if $|\mathcal{V}^i| = 2$ and a trimer if $|\mathcal{V}^i| = 3$. We say that $\mathcal{V}$ is an $(a,b)$ {\em dimer-or-timer} (DOT) clustering, denoted $\mathcal{V} \in \mathrm{Clust}_{a,b}^\bullet (V)$, if $\mathcal{V}$ satisfies
\begin{equation}\label{two or three elems}
|\mathcal{V}^i| \in \{2,3\}, \quad 1 \leq i \leq k,
\end{equation}
in addition to \eqref{abs rel sep}.

\begin{equation}\label{abs rel sep}
|\mathcal{V}^i| \geq 2, \quad \mathrm{dist} (\mathcal{V}^i, \mathcal{V}^{\neq i}) \geq a, \quad \text{and} \quad \mathrm{diam} (\mathcal{V}^i) \leq b \log \mathrm{dist} (\mathcal{V}^i, \mathcal{V}^{\neq i}), \quad 1 \leq i \leq k.
\end{equation}

\label{fate}
Let $d \geq 5$ and $n \geq 4$, and let $V \in \mathrm{Conf}_{d,n}$. There exists $b = b(d,n) > 0$ such that, for any $\delta \in (0,\frac12)$, there exist $a = a(d,n,\delta) > 0$ and a $\mathbf{P}_V$-a.s.\@ finite random time $\theta = \theta (d,n,\delta) \in \mathbb{N}$
 at which there is a clustering $\mathcal{W} \in \mathrm{Clust}_{a,b}^\bullet (U_\theta)$ such that the natural partitioning $(\mathcal{U}_t)_{t \geq \theta}$ of $(U_t)_{t \geq \theta}$ with $\mathcal{W}$ satisfies 
\begin{equation}\label{dot conds}
\mathcal{U}_t \in \mathrm{Clust}_{g(t-\theta),b}^\bullet (U_t), \quad t > \theta,
\end{equation}
where $g(s) = s^{\frac12 - \delta}$ for $s \geq 0$.

\label{thm form dot} Fix $d \geq 5$ and $n \geq 4$. For every $a > 0$, there exist $N = N (a,d,n) \in \mathbb{N}$ and $p = p(a,d,n) \in (0,1]$ such that, for any $V \in \mathrm{Conf}_{d,n}$,
\begin{equation}\label{thm eq form dot}
\mathbf{P}_{V} \left( \mathrm{Clust}_{a,1}^\bullet (U_N) \cap \mathrm{Ref}^\times \neq \emptyset \right) \geq p.
\end{equation}

\label{inf xi}
Fix $d \geq 5$ and $n \geq 4$. There exists $b = b (n) \geq 1$ such that, for any $\delta \in (0,\frac12)$, there exists $\alpha = \alpha (d,n,\delta) > 0$ such that, if $W \in \mathrm{Conf}_{d,n}$ has a clustering $\mathcal{W} \in \mathrm{Clust}_{\alpha,b}^\bullet (W) \cap \mathrm{Ref}^\times$, then 
\begin{equation}\label{eq inf xi}
\mathbf{P}_{W} (\xi = \infty) \geq \frac14,
\end{equation}
where $\xi$ is the first time that the natural clustering $(\mathcal{U}_t)_{t \geq 0}$ of $(U_t)_{t \geq 0}$ with $\mathcal{W}$ is not in $\mathrm{Clust}_{g(t),b}^\bullet (U_t)$ where $g(s) = s^{\frac12 - \delta}$ for $s \geq 0$, i.e., 
\[
\xi = \inf \{t \geq 0: \mathcal{U}_t \notin \mathrm{Clust}_{g(t),b}^\bullet (U_t)\}.
\]

Fix $d \geq 5$ and $n \geq 4$. Let $\alpha > 0$ and $b \geq 1$ be the constants from Proposition~\ref{inf xi}. Fix $\delta \in (0,\frac12)$. In these terms, denote $g(s) = s^{\frac12-\delta}$ for $s \geq 0$. Additionally, let $\psi$ be a function which, given a configuration $U \in \mathrm{Conf}_{d,n}$ that has a clustering in $\mathrm{Clust}_{\alpha,b}^\bullet (U)$, determines one such clustering. (We use $\psi$ to ``pick'' one of potentially multiple clusterings; it is otherwise unimportant.) 

We define $\theta$ in terms of two sequences of random times, $(\tau_i)_{i \geq 1}$ and $(\xi_i)_{i \geq 0}$. In words, $\tau_i$ is the first time $t \geq \xi_{i-1}$ at which $U_t$ has an $(\alpha,b)$ DOT clustering in $\mathrm{Ref}^\times$, and $\xi_i$ is the first time $t > \tau_i$ at which the natural clustering $(\mathcal{U}_t)_{t \geq \tau_i}$ of $(U_t)_{t \geq \tau_i}$ with $\psi (U_{\tau_i})$ is not a $(g(t-\tau_i),b)$ DOT clustering of $U_t$. More precisely, we define $\xi_0 = 0$ and, for $i \geq 1$,  
\begin{align*}
\tau_i &=  \inf \left\{t \geq \xi_{i-1}: \mathrm{Clust}_{\alpha,b}^\bullet (U_t) \cap \mathrm{Ref}^\times \neq \emptyset \right\}, \quad \text{and}\\ 
\xi_i &= \inf \left\{t > \tau_i: \mathcal{U}_t \notin \mathrm{Clust}_{ g(t-\tau_i),b}^\bullet (U_{t}) \right\}.
\end{align*}
Lastly, we define $\theta = \tau_I$ for $I = \inf \{i \geq 1: \tau_i < \infty, \xi_i = \infty\}$. By the definition of $\theta$, \eqref{dot conds} is satisfied, so it remains to show that $\theta$ is $\mathbf{P}_V$-a.s.\@ finite for every $V \in \mathrm{Conf}_{d,n}$.

Let $J =\inf \{j : \xi_j = \infty\}$. For every $V \in \mathrm{Conf}_{d,n}$, we have
\begin{equation}\label{thetatoj}
\mathbf{P}_V (\theta < \infty) = \mathbf{P}_V (I < \infty) = \mathbf{P}_V (J < \infty).
\end{equation}
The first equality follows from the definitions of $I$ and $\theta$. The second equality follows from the fact that $\mathbf{P}_V (\tau_i < \infty \mid \xi_{i-1} < \infty) = 1$, which is a simple consequence of Theorem~\ref{thm form dot}. 

To bound the tail probabilities of $J$, we write
\begin{equation}\label{jj2}
\mathbf{P}_V (J > j+1 \,|\, J > j) = \frac{\mathbf{E}_V \big[ \mathbf{P}_{U_{\tau_j}} (\xi_1 < \infty); J > j\big]}{\mathbf{P}_V (J > j)} \leq \frac{3}{4}.
\end{equation}
The equality follows from the strong Markov property applied at time $\xi_j$ and the fact that $\mathbf{P}_{U_{\xi_j}} (\tau_1 < \infty) = 1$. The inequality is due to Proposition~\ref{inf xi}, which implies that $\mathbf{P}_{U_{\tau_j}} (\xi_1 < \infty)$ is at most $\frac34$.

The bound \eqref{jj2} implies that $\mathbf{P}_V (J > j)$ is summable, so the Borel-Cantelli lemma implies that $J$ is $\mathbf{P}_V$-a.s.\@ finite, which by \eqref{thetatoj} implies the same of $\theta$.

\begin{equation}\label{jj2}
\mathbf{P}_V (J > j+1 \,|\, J > j) = \frac{\mathbf{E}_V \big[ \mathbf{P}_{U_{\tau_j}} (\xi_1 < \infty); J > j\big]}{\mathbf{P}_V (J > j)} \leq \frac{3}{4}.
\end{equation}

\begin{multline}\label{ict hat}
\mathbb{P}_x ( S_{\tau - 1} = y \mid \tau < \infty) = \mathbb{P}_x (S_{\tau_A - 1} = y \mid \tau_A < \infty)\\ 
\times \underbrace{\frac{\mathbb{P}_x (\tau_A < \infty)}{\mathbb{P}_x (\tau < \infty)}}_{( \ref{ict hat} \text{a})} \Bigg( 1 - \underbrace{\frac{\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_{\mathcal{C}^2} < \tau_A < \infty)}{\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_A < \infty)}}_{( \ref{ict hat} \text{b})} \Bigg).
\end{multline}

\begin{equation}\label{heur4}
\mathbb{P}_x (S_{\tau-1} = y \mid \tau < \infty) \geq \left(1 - O \left( |U| \left( b a^{-1} \log a \right)^{d-2} \right) \right) \, \mathbb{P}_x (S_{\tau_A-1} = y \mid \tau_A < \infty).
\end{equation}

Given $\mathcal{V}_t$, we define the transition probabilities in terms of 
\begin{equation}\label{eq tps q}
q_{\mathcal{V}_t} (i,x,y) = \mathbb{H}_{\mathcal{V}_t} (i,x) \, \mathbb{P}_x ( S_{\tau-1} = y \mid \tau < \infty), \quad 1 \leq i \leq \# \mathcal{V}_t, \quad x, y \in \mathbb{Z}^d,
\end{equation}
where $\tau$ abbreviates $\tau_{\mathcal{V}_t^i \setminus \{x\}}$.

\begin{equation}\label{eq tps q}
q_{\mathcal{V}_t} (i,x,y) = \mathbb{H}_{\mathcal{V}_t} (i,x) \, \mathbb{P}_x ( S_{\tau-1} = y \mid \tau < \infty), \quad 1 \leq i \leq \# \mathcal{V}_t, \quad x, y \in \mathbb{Z}^d,
\end{equation}


IHAT is the discrete-time Markov chain $(\mathcal{V}_t)_{t \geq 0}$ on the state space $\mathrm{Conf}_d^\times$ with the following transition probabilities given by 
\begin{equation}\label{eq tps pprod}
\mathbf{Q} \left( \mathcal{V}_{t+1} = (\mathcal{V}_t \sd{i} \{x\}) \cup^i \{y\} \bigm\vert \mathcal{V}_t \right) = 
\begin{cases}
q_{\mathcal{V}_t} (i,x,y) & x \neq y,\\ 
\sum_{j=1}^{\# \mathcal{V}_t} \sum_{z \in \mathbb{Z}^d} q_{\mathcal{V}_t} (j,z,z) & x = y,
\end{cases}
\end{equation}
for $1 \leq i \leq \# \mathcal{V}_t$ and $x,y \in \mathbb{Z}^d$. We denote the law of IHAT from $\mathcal{V}$ by $\mathbf{Q}_{\mathcal{V}}$.

\begin{equation}\label{eq tps pprod}
\mathbf{Q} \left( \mathcal{V}_{t+1} = (\mathcal{V}_t \sd{i} \{x\}) \cup^i \{y\} \bigm\vert \mathcal{V}_t \right) = 
\begin{cases}
q_{\mathcal{V}_t} (i,x,y) & x \neq y,\\ 
\sum_{j=1}^{\# \mathcal{V}_t} \sum_{z \in \mathbb{Z}^d} q_{\mathcal{V}_t} (j,z,z) & x = y,
\end{cases}
\end{equation}

Our basic tool is Green's function $G(x)$, which is defined in $d \geq 3$ dimensions as the expected number of visits to $x$ by random walk from the origin: 
\begin{equation}\label{eq green}
G(x) = \mathbb{E}_o \left[ \sum_{j=0}^\infty \mathbf{1} (S_j = x) \right], \quad x \in \mathbb{Z}^d.
\end{equation}

\label{simple set hit}
Let $x \in \mathbb{Z}^d$ and let $A \subset \mathbb{Z}^d$ be nonempty and finite. If $\mathrm{dist} (x,A) \geq 1$, then
\begin{equation}\label{eq simple set hit lb}
\mathbb{P}_x (\tau_A < \infty) \gtrsim \mathrm{dist} (x, A)^{2-d}.
\end{equation}
If $\mathrm{dist} (x, A) \geq \kappa$, then
\begin{equation}\label{eq simple set hit ub}
\mathbb{P}_x (\tau_A < \infty) \lesssim |A| \mathrm{dist} (x,A)^{2-d}.
\end{equation}

\label{min es}
Let $d \geq 4$. If $U \subset \mathbb{Z}^d$ has $|U| \leq 4$, then
\begin{equation}\label{eq min es2}
\mathrm{esc}_U (x) \geq \frac{4 - 3 G(o)}{G(o)} \geq \frac15 \quad \text{and} \quad \mathbb{H}_U (x) \geq \frac{1}{16}, \quad x \in U.
\end{equation}

\begin{equation*}
\sum_{y \in U} G(x-y) \leq G(o) + G(u) + G(v) + G(w) \leq G(o) + G(e_k) + G(e_l) + G(e_m).
\end{equation*}

\label{min hm}
Let $d \geq 4$. There is a constant $c = c(d)$ such that, if $U \in \mathrm{Conf}_d$ can be partitioned into $\mathcal{P} = (\mathcal{P}^1, \mathcal{P}^2)$ such that $|\mathcal{P}^1| \leq 4$ and $\mathrm{sep} (\mathcal{P}) \geq \kappa$, then 
\begin{equation*}
\mathrm{esc}_U (x) \geq \left( 1 - c |U| \mathrm{sep} (\mathcal{P})^{2-d} \right) \mathrm{esc}_{\mathcal{P}^1} (x), \quad x \in \mathcal{P}^1.
\end{equation*}

Let $U$ and $\mathcal{P}$ satisfy the hypotheses and let $x \in \mathcal{P}^1$. We bound below $\mathrm{esc}_U (x)$ as
\begin{align*}
\mathrm{esc}_U (x) &= \mathrm{esc}_{\mathcal{P}^1} (x) - \mathbb{P}_x (\tau_{\mathcal{P}^1} = \infty, \tau_{\mathcal{P}^2} < \infty)\\ 
&\geq \left(1 - \frac{\mathbb{P}_x (\tau_{\mathcal{P}^2} < \infty)}{\mathrm{esc}_{\mathcal{P}^1} (x)} \right) \mathrm{esc}_{\mathcal{P}^1} (x) \geq \left(1 - O \left( |U| \mathrm{sep} (\mathcal{P}^{2-d}) \right) \right) \mathrm{esc}_{\mathcal{P}^1} (x).
\end{align*}
The first inequality follows from dropping the sub-event $\{\tau_{\mathcal{P}^1} = \infty\}$; the second uses the bound $\mathrm{esc}_{\mathcal{P}^1} (x) \geq \frac15$ from Lemma~\ref{min es}, which applies because $|\mathcal{P}^1| \leq 4$, and equation \eqref{eq simple set hit ub} of Lemma~\ref{simple set hit}, which applies because $\mathrm{sep} (\mathcal{P}) \geq \kappa$.

\label{lemma help est}
Let $d \geq 4$. There is a constant $c = c(d)$ such that, if $U \in \mathrm{Conf}_d$ can be partitioned into $\mathcal{P} = (\mathcal{P}^1, \mathcal{P}^2)$ such that $|\mathcal{P}^1| \leq 3$ and $\mathrm{sep} (\mathcal{P}) \geq \kappa$, then, for every $x \in \mathcal{P}^1$ and every $y$ in the exterior boundary of $A = \mathcal{P}^1 {\setminus} \{x\}$, 
\begin{align}
\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_{\mathcal{P}^2} < \tau_A < \infty) &\leq c |U| \mathrm{sep} (\mathcal{P})^{4-2d}, \quad \quad \text{and} \label{help est1}\\ 
\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_A < \infty) &\geq c \mathrm{diam} (A \cup \{y\})^{2-d}. \label{help est2}
\end{align}

\begin{align}
\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_{\mathcal{P}^2} < \tau_A < \infty) &\leq c |U| \mathrm{sep} (\mathcal{P})^{4-2d}, \quad \quad \text{and} \label{help est1}\\ 
\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_A < \infty) &\geq c \mathrm{diam} (A \cup \{y\})^{2-d}. \label{help est2}
\end{align}

\begin{equation}\label{hm like bd}
\mathbb{P}_x (S_{\tau_A - 1} = y, \tau_A < \infty) \geq \frac{1}{2d} \mathbb{P}_x (\tau_{\partial C} < \tau_B < \infty, S_{\tau_B} = y).
\end{equation}

\label{prop h comp}
Let $d \geq 4$. There is a constant $c = c (d)$ such that, if $U \in \mathrm{Conf}_d$ can be partitioned into $\mathcal{P} = (\mathcal{P}^i)_{i=1}^k$ such that $|\mathcal{P}^i| \leq 3$ for every $1 \leq i \leq k$ and $\mathrm{sep} (\mathcal{P}) \geq \kappa$, then 
\begin{equation}\label{hm for laycon}
\mathbb{H}_U (x) \geq \big(1 - c |U| \mathrm{sep}(\mathcal{P}) ^{2-d} \big) \mathbb{H}_{\mathcal{P}} ([x]_{\mathcal{P}},x), \quad x \in U.
\end{equation}

\label{prop t comp}
Let $a \geq \kappa$, $b > 0$, and $d \geq 4$. There is a constant $c = c(b,d)$ such that, if $U \in \mathrm{Conf}_d$ has an $(a,b)$ DOT clustering $\mathcal{P}$, 
then, for every $x \in U$ and every $y$ in the exterior boundary of $A = \mathcal{P}^{[x]_{\mathcal{P}}} {\setminus} \{x\}$, 
\begin{equation*}
\mathbb{P}_x (S_{\tau_{U {\setminus} \{x\}}-1} = y \,\vert\, \tau_{U {\setminus} \{x\}} < \infty) \geq \left(1 - c |U| \left( \frac{\log \mathrm{sep} (\mathcal{P})}{\mathrm{sep} (\mathcal{P})} \right)^{d-2} \right) \mathbb{P}_x (S_{\tau_A-1} = y \,\vert\, \tau_A < \infty).
\end{equation*}

\begin{multline}\label{inc hat1}
\mathbb{P}_x (S_{\tau-1} = y \,|\, \tau < \infty) = \mathbb{P}_x (S_{\tau_A-1} = y \,|\, \tau_A < \infty)\\ 
\times \underbrace{\frac{\mathbb{P}_{x} (\tau_A < \infty)}{\mathbb{P}_{x} (\tau < \infty)}}_{( \ref{inc hat1} \text{a})} \Bigg( 1
- \underbrace{\frac{\mathbb{P}_{x} (S_{\tau_A-1} = y, \tau_{\mathcal{C}^2} < \tau_A < \infty)}{\mathbb{P}_{x} (S_{\tau_A-1} =y, \tau_A < \infty)}}_{( \ref{inc hat1} \text{b})} \Bigg).
\end{multline}

For $\delta \in (0,\frac12)$, we define the following set of infinite sequences of $(a,b)$ DOT clusterings:
\begin{equation}\label{event grow}
\mathrm{Grow}_{a,b,\delta} = \left\{ (\mathcal{C}_t)_{t \geq 0} \in (\mathrm{Clust}_{a,b}^\bullet)^{\mathbb{N}}: \mathrm{sep} (\mathcal{C}_t) \geq t^{\frac12-\delta} \,\,\text{for every $t \geq 0$} \right\}.
\end{equation}

\label{p to q}
Fix $d \geq 5$ and $n \geq 4$, and let $a,b > 0$. There are constants $\alpha_0 = \alpha_0 (b,d,n)$ and $c = c(b,d,n)$ such that, if $a \geq \alpha_0$, then, for every $\mathcal{C}_0, \mathcal{C}_1 \in \mathrm{Clust}_{a,b}^\bullet$,
\begin{equation}\label{eq p to q}
\mathbf{P}_{\mathcal{C}_0} (\mathcal{U}_1 = \mathcal{C}_1) \geq \left( 1 - c \left(a^{-1} \log a\right)^{d-2} \right) \mathbf{Q}_{\mathcal{C}_0} (\mathcal{V}_1 = \mathcal{C}_1).
\end{equation}

\begin{equation}\label{multistep h}
\mathbf{P}_{\mathcal{C}_0} \left( \mathcal{U}_s = \mathcal{D}_s, s \leq t \right) \geq h(t) \mathbf{Q}_{\mathcal{C}_0} \left( \mathcal{V}_s = \mathcal{D}_s, s \leq t \right).
\end{equation}

\label{help for at pairs}
Fix $d \geq 5$ and $n \geq 4$. Let $a, b > 0$, and let $\mathcal{C} \in \mathrm{Clust}_{a,b}^\bullet$. If $a \geq \max\{e^{2b},8\sqrt{d}\}$, then
\begin{align*}
\mathrm{esc}_{\mathcal{C}^i} (x) > 0 \implies \mathrm{esc}_{\cup_j \mathcal{C}^j} (x) > 0, \quad x \in \mathbb{Z}^d.
\end{align*}

\label{at pairs}
Fix $d \geq 5$ and $n \geq 4$. Let $a,b > 0$, let $\mathcal{C}_0, \mathcal{C}_1 \in \mathrm{Clust}_{a,b}^\bullet$, and denote $U_0 = \cup_j \mathcal{C}_0^j$. If $a$ is at least $\max\{e^{2b},8\sqrt{d}\}$,  
then, for any $x \in U_0$ and $y \in \mathbb{Z}^d$ such that 
\begin{equation}\label{c0 to c1 equiv}
\mathcal{C}_1 = (\mathcal{C}_0 \sd{[x]_{\mathcal{C}_0}} \{x\}) \cup^{[x]_{\mathcal{C}_0}} \{y\},
\end{equation}
the following equivalence holds
\begin{equation}\label{corresp}
p_{U_0} (x,y) > 0 \iff q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y) > 0.
\end{equation}

Recall the constant $\kappa$ that appears in the statements of Propositions~\ref{prop h comp} and \ref{prop t comp}. Let $b > 0$ and $a \geq \max \{e^{2b},8\sqrt{d}, \kappa\}$, let $\mathcal{C}_0, \mathcal{C}_1 \in \mathrm{Clust}_{a,b}^\bullet$, and denote $U_0 = \cup_j \mathcal{C}_0^j$.

By the definition of the natural partitioning of HAT with $\mathcal{C}_0$ (Definition~\ref{nat part}),
\begin{equation}\label{sum puo}
\mathbf{P}_{\mathcal{C}_0} (\mathcal{U}_1 = \mathcal{C}_1) = \sum p_{U_0} (x,y),
\end{equation}
where the sum ranges over $x \in U_0$ and $y \in \mathbb{Z}^d$ that satisfy $\mathcal{C}_1 = (\mathcal{C}_0 \sd{[x]_{\mathcal{C}_0}} \{x\}) \cup^{[x]_{\mathcal{C}_0}} \{y\}$. According to Proposition~\ref{at pairs}, since $\mathrm{sep} (\mathcal{C}_0)$ is at least $\max \{e^{2b}, 8 \sqrt{d}\}$, the summand in \eqref{sum puo} is positive if and only if $q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y)$ is. Moreover, since $\mathcal{C}_0$ is a partition of $U_0$, $q_{\mathcal{C}_0} (j,x,y) = 0$ for every $j \neq [x]_{\mathcal{C}_0}$. Hence,
\begin{equation}\label{sum quo}
\mathbf{Q}_{\mathcal{C}_0} (\mathcal{V}_1 = \mathcal{C}_1) = \sum q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y),
\end{equation}
where the sum ranges over the same $x$ and $y$ as in \eqref{sum puo}.

Since $\mathcal{C}_0$ is a DOT clustering with a separation of at least $a \geq \kappa$, Propositions~\ref{prop h comp} and \ref{prop t comp} together imply that there is a constant $c = c (b,d,n)$ such that 
\begin{equation}\label{pq comp}
p_{U_0} (x,y) \geq \left(1 - c \left( a^{-1} \log a \right)^{d-2} \right) q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y).
\end{equation}
 We apply this bound to \eqref{sum puo} and then use \eqref{sum quo} to conclude that
\[
\mathbf{P}_{\mathcal{C}_0} (\mathcal{U}_1 = \mathcal{C}_1) \geq \left(1 - c \left( a^{-1} \log a \right)^{d-2} \right) \mathbf{Q}_{\mathcal{C}_0} (\mathcal{V}_1 = \mathcal{C}_1).
\]

\begin{equation}\label{pq comp}
p_{U_0} (x,y) \geq \left(1 - c \left( a^{-1} \log a \right)^{d-2} \right) q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y).
\end{equation}

For every distinct pair of clusters $i, j \in \{1, \dots, \# \mathcal{V}_0\}$ with $i < j$, we define a random walk $(S_k^{i,j})_{k \geq 0}$ by 
\begin{equation}\label{rw assoc w}
S_0^{i,j} = M_{\xi_0}^i - M_{\xi_0}^j \quad \text{and} \quad S_k^{i,j} = S_{k-1}^{i,j} + \left( M_{\xi_k}^i - M_{\xi_k}^j - \left( M_{\xi_{k-1}}^i + M_{\xi_{k-1}}^j\right) \right), \quad k \geq 1.
\end{equation}

\begin{equation}\label{rw assoc w}
S_0^{i,j} = M_{\xi_0}^i - M_{\xi_0}^j \quad \text{and} \quad S_k^{i,j} = S_{k-1}^{i,j} + \left( M_{\xi_k}^i - M_{\xi_k}^j - \left( M_{\xi_{k-1}}^i + M_{\xi_{k-1}}^j\right) \right), \quad k \geq 1.
