\label{lem hm comp}
Let $d \geq 5$ and $n \geq 2$. There is a constant $c = c(d,n)$ such that, if $A \cup B \in \mathrm{Conf}_{d,n}$ such that $A$ is connected and $\mathrm{dist} (A,B) \geq 4^d n$, then, for any distinct $x, y \in A$ that are exposed in $A \cup B$,
\begin{equation}\label{hm comp}
\mathbb{H}_{A \cup B} (x) \geq c \mathbb{H}_{A \cup B} (y).
\end{equation}

\label{lex hm}
Let $d \geq 5$ and $n \geq 2$. There are constants $r = r (d,n)$ and $c = c(d)$ such that, if $A \cup B \in \mathrm{Conf}_{d,n}$ satisfies $\mathrm{dist} (A,B) \geq r$ and if $x$ is lex in $A$, then
\begin{equation}\label{lex hm bd1}
\mathrm{esc}_{A \cup B} (x) \geq  c n^{-\frac{1}{d-2}-o_d(1)} 
\end{equation}
and, consequently,
\begin{equation}\label{lex hm bd2}
\mathbb{H}_{A \cup B} (x) \geq c n^{-\frac{d-1}{d-2}-o_d(1)}.
\end{equation}
For concreteness, the $o_d (1)$ quantities are never larger than $0.8$ when $d \geq 5$, and the two lower bounds can be replaced with $cn^{-1.2}$ and $c n^{-2.2}$.

\begin{equation}\label{lex esc bd3}
\mathbb{P}_x (\tau_{A \cup B} = \infty \mid \tau_{X_1} < \tau_{\partial C} < \tau_{A \cup B}) \geq \min_{z \in \partial C} \mathbb{P}_z \left( \tau_{A \cup B} = \infty \right) \geq 1 - n 2^{-k(d-2)}.
\end{equation}

\label{lex hm2}
Let $d \geq 5$. There are constants $r = r (n,d)$ and $c = c(d)$ such that if $x$ is lex in $A$, if $A \cup B \in \mathrm{Conf}_{d,n}$ such that $\mathrm{dist} (A,B) \geq r$, and if $B$ can be written as a disjoint union $B^1 \cup B^2$ where $|B^1| \leq 3$ and $\mathrm{dist} (B^1, B^2) \geq r$, then
\begin{equation}\label{eq lex hm2}
\mathbb{P}_x \big( S_{\tau_{A\cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \geq c n^{-\frac{d}{d-2}-o_d(1)} \mathrm{diam} (A \cup B)^{2-d}.
\end{equation}
For concreteness, the $o_d (1)$ quantity is smaller than $1.6$ when $d \geq 5$.

\begin{equation}\label{eq lex hm2}
\mathbb{P}_x \big( S_{\tau_{A\cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \geq c n^{-\frac{d}{d-2}-o_d(1)} \mathrm{diam} (A \cup B)^{2-d}.
\end{equation}

Let $A$, $B$, $B^1$, and $B^2$ satisfy the hypotheses for the $r$ in the statement of Lemma \ref{lex hm}. Additionally, denote by $F$ the set of points within a distance $r \mathrm{diam} (A \cup B)$ of $A \cup B$. Applying the strong Markov property to $\tau_{F^{\mathsf{c}}}$, we write
\begin{multline}\label{lex cond hit}
\mathbb{P}_x \big( S_{\tau_{A\cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big)\\
 \geq \mathbb{E}_x \Big[ \mathbb{P}_{S_{\tau_{F^{\mathsf{c}}}}} \big( S_{\tau_{A \cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \mathbb{P}_{S_{\tau_{F^{\mathsf{c}}}}} \big( \tau_{A \cup B} < \infty \big); \tau_{F^{\mathsf{c}}} < \tau_{A \cup B}\Big].
\end{multline}

A standard result (e.g., \cite[Theorem 2.1.3]{lawler2013intersections}) implies that for all sufficiently large $r$, if $y$ belongs to $F^{\mathsf{c}}$, then
\begin{equation}\label{lex cond hit0}
\mathbb{P}_y \big( S_{\tau_{A \cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \geq \frac12 \mathbb{H}_{A \cup B} (B^1).
\end{equation}
Because $B^1 \cup (A \cup B^2)$ satisfies the hypotheses of Lemma \ref{lex hm},
\begin{equation}\label{lex cond hit1}
\mathbb{H}_{A \cup B} (B^1) \gtrsim c_1 n^{-\frac{d-1}{d-2}-o_d(1)}.
\end{equation} 
By Lemma~\ref{simple set hit}, for any $y \in F^{\mathsf{c}}$, we have
\begin{equation}\label{lex cond hit2}
\mathbb{P}_y \big( \tau_{A \cup B} < \infty \big) \gtrsim \mathrm{dist} (y,A \cup B)^{2-d}.
\end{equation}
Lastly, by Lemma \ref{lex hm}, the probability of hitting $F^{\mathsf{c}}$ before returning to $A \cup B$ satifies
\begin{equation}\label{lex cond hit3}
\mathbb{P}_x (\tau_{F^{\mathsf{c}}} < \tau_{A \cup B} ) \geq \mathrm{esc}_{A\cup B} (x) \gtrsim n^{-\frac{1}{d-2} - o_d(1)}.
\end{equation}

Applying \eqref{lex cond hit0} through \eqref{lex cond hit3} to \eqref{lex cond hit}, we conclude that
\[ 
\mathbb{P}_x \big( S_{\tau_{A\cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big)
\gtrsim n^{-\frac{d}{d-2}-o_d(1)} \mathrm{diam} (A \cup B)^{2-d}.
\] Here, $o_d(1)$ can be taken to be $1.6$ when $d \geq 5$.

\begin{multline}\label{lex cond hit}
\mathbb{P}_x \big( S_{\tau_{A\cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big)\\
 \geq \mathbb{E}_x \Big[ \mathbb{P}_{S_{\tau_{F^{\mathsf{c}}}}} \big( S_{\tau_{A \cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \mathbb{P}_{S_{\tau_{F^{\mathsf{c}}}}} \big( \tau_{A \cup B} < \infty \big); \tau_{F^{\mathsf{c}}} < \tau_{A \cup B}\Big].
\end{multline}

\begin{equation}\label{lex cond hit0}
\mathbb{P}_y \big( S_{\tau_{A \cup B}} \in B^1 \bigm\vert \tau_{A \cup B} < \infty \big) \geq \frac12 \mathbb{H}_{A \cup B} (B^1).
\end{equation}

\begin{equation}\label{lex cond hit3}
\mathbb{P}_x (\tau_{F^{\mathsf{c}}} < \tau_{A \cup B} ) \geq \mathrm{esc}_{A\cup B} (x) \gtrsim n^{-\frac{1}{d-2} - o_d(1)}.
\end{equation}

