  \caption{Algorithm $\mathcal{A}_1$}
\label{alg1}

\label{follow alg1}
Let $U \in \mathrm{Conf}_{d,n}$. There exists $\alpha_1 = \alpha_1 (d,n) \in \mathbb{Z}_{\geq 1}$ such that, if $a \geq \mathbb{Z}_{\geq \alpha_1}$, then there are $N_1 = N_1 (a,d,n) \in \mathbb{N}$ and $p_1 = p_1 (a,d,n) \in (0,1]$ such that 
\begin{equation}\label{eq follow alg1}
\mathbf{P}_U \Big( U_{N_1} = \pi \big( \mathcal{A}_{\ref{alg1}} (U,a) \big) \Big) \geq p_1.
\end{equation}

The proof takes the form of an analysis of Algorithm $\mathcal{A}_{\ref{alg1}}$. Denote by $u_{k}$ the configuration $U \cup \pi (\mathcal{C})$ after the $k$\textsuperscript{th} time $U \cup \pi (\mathcal{C})$ is changed (i.e., an element is moved) by the algorithm. Additionally, denote by $M$ the number of times the configuration changes before the outer {\bf while} loop terminates. 

To establish \eqref{eq follow alg1}, it suffices to show that there is a sequence of times $t_0 = 0 \leq t_1 < t_2 < \cdots < t_M \leq N_1$ such that $u_{0} = U$, $u_{M} = \pi \big( \mathcal{A}_{\ref{alg1}} (U,a) \big)$, and
\begin{equation}\label{alg bd1}
\mathbf{P}_{u_0} \big( U_{t_1} = u_1, U_{t_2} = u_2, \dots, U_{t_M} = u_{M} \big) \geq p_1.
\end{equation}


We will argue that $M \leq n(n+1)$, that we can take $t_M = n(n+1)r_1$ for $r_1 = 3dn^3 a$, and that
\begin{equation}\label{alg bd22}
\mathbf{P}_{u_{k-1}} \big( U_{t_k} = u_k \big) \geq q,
\end{equation}
for each $k \in \{1,\dots,M\}$, for a constant $q = q(a,d,n) > 0$. The Markov property then implies that \eqref{alg bd1} holds with $N_1 = n(n+1)r_1$ and $p_1 = q^{n(n+1)}$.


{\em Claim 1}. We claim that $M \leq n(n+1)$. Observe that the outer and inner {\bf while} loops starting on lines {\bf 2} and {\bf 5} each repeat at most $n$ times. Indeed, $U$ loses an element every time the outer loop repeats, which can happen no more than $n$ times. Concerning the inner loop, no non-isolated element is made to be isolated, while, each time line {\bf 6} is executed, the isolated element $\ell$ is replaced by an element $x$ which is non-isolated. This can happen at most $n$ times consecutively. Accordingly, $U \cup \pi (\mathcal{C})$ changes at most $n+1$ times every time the outer loop repeats, hence $M \leq n (n+1)$.

{\em Claim 2}. We now claim that we can take $t_M = n(n+1)r_1$. It suffices to argue that, each time $U \cup \pi (\mathcal{C})$ changes, at most $r_1$ steps of HAT are required to realize the change. The configuration $U \cup \pi (\mathcal{C})$ changes due to the execution of lines {\bf 8}, {\bf 10} and {\bf 11}, {\bf 18} and {\bf 19}, or {\bf 23} and {\bf 24}. In all but one case---that of lines {\bf 18} and {\bf 19}---the transition requires only one HAT step. For lines {\bf 18} and {\bf 19}, at most $r_1$ steps are needed. Because there are at most $n(n+1)$ changes, $t_M$ can be taken to be $n(n+1)r_1$.

{\em Claim 3}. We now verify \eqref{alg bd22} by considering each way $U \cup \pi (\mathcal{C})$ can change and by bounding below the probability that it is realized by HAT. Assume $U \cup \pi (\mathcal{C})$ has changed $k-1$ times so far.
\begin{itemize}
\item Lines {\bf 8}, {\bf 10} and {\bf 11}, or {\bf 23} and {\bf 24}: Activation at $\ell$ and transport to $x$. Assume that $a$ is sufficiently large in $d$ and $n$ to exceed the constant $r$ in the statement of Lemma \ref{lex hm}. Then, since $\ell$ is the lex element of $U$ and since $\mathrm{dist} (U, \pi (\mathcal{C})) \geq a$, we can apply Lemma \ref{lex hm} with $A = U$ and $B = \pi (\mathcal{C})$ to find that
\begin{equation}\label{h lw bd} 
\mathbb{H}_{U \cup \pi (\mathcal{C})}(\ell) \geq h,
\end{equation}
for a positive number $h = h(d,n)$. By the definition of $\mu$, $x$ is the most likely destination of an element activated at $\ell$. Transport from $\ell$ occurs to at most $2dn$ sites and so, by the pigeonhole principle, the element from $\ell$ is transported to $x$ with a probability of at least $(2dn)^{-1}$. Together, these bounds imply that
\begin{equation}\label{claim3 bd1}
\mathbf{P}_{u_{k-1}} \big( U_{t_k} = u_k \big) \geq h (2dn)^{-1}.
\end{equation}
\item Lines {\bf 18} and {\bf 19}: Treadmilling of $\{\ell,y\}$. In the first step, we activate at $y$ and transport to $\ell-e_1$. While $y$ is not lex in $U$, by the definition of $\mathrm{expo}$, it is an exposed neighbor of $\ell$. Because $\mathrm{dist} (U, \pi (\mathcal{C})) \geq a$, if $a$ is at least $4^d n$, we can apply Lemma \ref{lem hm comp} with $A = U$ and $B = \pi (\mathcal{C})$ to conclude that $\mathbb{H}_{U \cup \pi (\mathcal{C})} (y)$ is at least $c_1 h$ from \eqref{h lw bd}, for a positive number $c_1 = c_1 (d,n)$. Additionally, Lemma \ref{kesten cor} implies that an element activated at $y$ is transported to $\ell-e_1$ with a probability of at least $c_2 = c_2 (d,n)$. Consequently, denoting
\[
v_1 = \big( u_{k-1} \cup \{\ell-e_1,\ell\} \big) {\setminus} \{\ell,y\},
\]
we have
\begin{equation}\label{claim3 bd2}
\mathbf{P}_{u_{k-1}} (U_1 = v_1) \geq c_1 c_2 h.
\end{equation}

Now, consider the configuration $v_m$ resulting from starting at $u_{k-1}$ and treadmilling $\{\ell,y\}$ a total of $m \geq 2$ steps in the $-e_1$ direction:
\[ v_m = \big( u_{k-1} \cup \{\ell-me_1, \ell - (m-1)e_1\} \big) {\setminus} \{\ell,y\}.\]
To obtain $v_{m+1}$, we activate at $\ell-(m-1)e_1$ and transport to $\ell-(m+1)e_1$. By the same reasoning as before,
\begin{equation}\label{claim3 bd3}
\mathbf{P}_{v_m} \big( U_1 = v_{m+1} \big) \geq c_1c_2 h.
\end{equation}
By \eqref{claim3 bd2}, \eqref{claim3 bd3}, and the Markov property,
\begin{equation}\label{claim3 bd4}
\mathbf{P}_{u_{k-1}} \big( U_{t_k} = u_k \big) \geq \big(c_1 c_2 h \big)^{r_1}.
\end{equation}
\end{itemize}

The bounds \eqref{claim3 bd1} and \eqref{claim3 bd4} show that, whenever $U \cup \pi (\mathcal{C})$ changes, the change can be realized by HAT (in one or more steps) with a probability of at least
\[ q = \min \big\{ h (2dn)^{-1}, (c_1c_2h)^{r_1} \big\}. \]
This proves \eqref{alg bd22}. We complete the proof by combining claims 1--3. Note that, to apply Lemma~\ref{lem hm comp} and Lemma~\ref{lex hm}, we assumed that $a$ was at least $\alpha_1 \in \mathbb{Z}_{\geq 1}$, where $\alpha_1$ is an integer which is at least $4^d n$ and the constant $r = r(d,n)$ from Lemma~\ref{lex hm}.

\begin{equation}\label{alg bd1}
\mathbf{P}_{u_0} \big( U_{t_1} = u_1, U_{t_2} = u_2, \dots, U_{t_M} = u_{M} \big) \geq p_1.
\end{equation}

The algorithm dictates a sequence of HAT steps that form the tuple
\begin{equation}\label{lined up tuple}
\mathcal{L} (C) = \big( \mathrm{lex} (\mathcal{C}^i) + L_{|\mathcal{C}^i|} \big)_{i=1}^{\# \mathcal{C}} \in \mathrm{Conf}_{d,n}^\times,
\end{equation}
where $L_k$ denotes the line segment of length $k$ from the origin to $-(k-1)e_1$ \eqref{line segment}.

