\label{break lines}
There exists $\alpha_3 = \alpha_3 (d,n) \in \mathbb{Z}_{\geq 1}$ such that, if $a \in \mathbb{Z}_{\geq \alpha_3}$, then there are $N_3 = N_3 (a,d,n) \in \mathbb{N}$ and $p_3 = p_3 (a,d,n) \in (0,1]$ such that, if $\mathcal{C} \in \mathrm{Conf}_{d,n}^\times$ can be lined-up with separation $n^2 a$, then 
\begin{equation}\label{eq rearrange small2}
\mathbf{P}_{U} \Big( U_{N_3} = \pi \big( \mathcal{A}_{\ref{alg3}} (\mathcal{L}(\mathcal{C}),a) \big) \Big) \geq p_3.
\end{equation}

As in the proof of Proposition \ref{alg3 works}, denote by $\mathcal{D}_k$ the clustering $\mathcal{D}_0 = \mathcal{L} (\mathcal{C})$ once it has been changed by the algorithm for the $k$\textsuperscript{th} time (i.e., the $k$\textsuperscript{th} time line {\bf 5} is executed). Denote by $M$ the number of times algorithm $\mathcal{A}_{\ref{alg3}}$ changes $\mathcal{D}_0$. Call $u_k = \pi (\mathcal{D}_k)$.

To establish \eqref{eq rearrange small2}, it suffices to show that there is a sequence of times $t_0 = 0 \leq t_1 < t_2 < \cdots < t_M \leq N_3$ such that $u_{0} = U$, $u_{M} = \pi \big( \mathcal{A}_{\ref{alg3}} (\mathcal{D}_0,a) \big)$, and
\begin{equation}\label{alg3 bd1}
\mathbf{P}_{u_0} \big( U_{t_1} = u_1, U_{t_2} = u_2, \dots, U_{t_M} = u_{M} \big) \geq p_3.
\end{equation}

Consider outer {\bf for} loop $i$, inner {\bf for} loop $j$, and suppose that $\mathcal{D}_0$ has been changed a total of $k-1$ times thus far. Let $r = 2(n-j)a$. We will first bound below the probability that HAT realizes $u_k$ as $U_{r}$ from $u_{k-1}$ (i.e., the transition reflected in line {\bf 5}). HAT can realize this transition by treadmilling the elements at $\ell = \mathrm{lex} (\mathcal{D}_{k-1}^i)$ and $\ell+e_1$ to $\{\ell - re_1,\ell-(r-1)e_1\}$.

For example, in the first step, we activate at $\ell+e_1$ and transport to $\ell-e_1$. As observed in the proof of Proposition \ref{alg3 works}, $\mathcal{D}_k$ is $a$ separated for every $0 \leq k \leq M$. Denote by $\alpha_3$ an integer at least as large as $4^d n$ and the constant $r$ from Lemma~\ref{lex hm}. If $a \in \mathbb{Z}_{\geq \alpha_3}$, then the hypotheses of Lemma \ref{lem hm comp} and Lemma \ref{lex hm} are satisfied with $A = \pi (\mathcal{D}_k^i)$ and $B = \pi (\mathcal{D}_k^{\neq i})$, and they together imply the existence of a positive lower bound $h = h(d,n)$ on $\mathbb{H}_{u_{k-1}} (\ell+e_1)$. It is clear that the element at $\ell+e_1$ can be transported to $\ell-e_1$ with a probability of at least $c = c(d)$, and so, denoting
\[
v_s = \big( u_{k-1} \cup \{\ell-s e_1,\ell - (s-1) e_1 \} \big) {\setminus} \{ \ell,\ell+e_1\},
\]
we have
\begin{equation*}
\mathbf{P}_{u_{k-1}} ( U_1 = v_1 ) \geq ch.
\end{equation*}

We can simply repeat this argument with $\ell$ and $\ell-e_1$ in the place of $\ell+e_1$ and $\ell$, then $\ell-e_1$ and $\ell-2e_1$, and so on. With the choice $u_k = v_r$, the Markov property implies
\begin{equation}\label{alg3 bd3}
\mathbf{P}_{u_{k-1}} (U_{r} = u_k) \geq (ch)^{r}.
\end{equation}
The same bound \eqref{alg3 bd3} holds for any $k \in \{1, \dots, M\}$, so, by another use of the Markov property and the fact that $M \leq n$, we find
\begin{equation}
\mathbf{P}_{u_0} \big( U_{r} = u_1, U_{2r} = u_2, \dots, U_{Mr} = u_M \big) \geq (ch)^{rn}.
\end{equation}
This proves \eqref{alg3 bd1} with $N_3 = nr$ and $p_3 = (ch)^{rn}$.

\begin{equation}\label{alg3 bd1}
\mathbf{P}_{u_0} \big( U_{t_1} = u_1, U_{t_2} = u_2, \dots, U_{t_M} = u_{M} \big) \geq p_3.
\end{equation}

\begin{equation}
\mathbf{P}_{u_0} \big( U_{r} = u_1, U_{2r} = u_2, \dots, U_{Mr} = u_M \big) \geq (ch)^{rn}.
\end{equation}

Let $U \in \mathrm{Conf}_{d,n}$. It suffices to prove the result when $a$ is sufficiently large, because if $\mathcal{C} \in \mathrm{Clust}_{a,1}^\bullet$ and $0 < a' \leq a$, then $\mathcal{C} \in \mathrm{Clust}_{a',1}^\bullet$. With this in mind, denote by $\alpha = \alpha (d,n)$ the largest of the integers $\alpha_1$ through $\alpha_3$ in Propositions \ref{follow alg1}, \ref{rearrange small}, and \ref{break lines}, and assume that $a \in \mathbb{Z}_{\geq \alpha}$. By Proposition \ref{follow alg1}, there are positive numbers $N_1 = N_1 (a,d,n)$ and $p_1 = p_1 (a,d,n)$ such that
\begin{equation}\label{thm14 conc1}
\mathbf{P}_U \Big( U_{N_1} = \pi \big(\mathcal{A}_{\ref{alg1}} (U, a) \big) \Big) \geq p_1.
\end{equation}
By Proposition \ref{alg1 works}, $\mathcal{C}_1 = \mathcal{A}_{\ref{alg1}} (U, a)$ can be lined-up with separation $d n^2 a$. Consequently, by Proposition \ref{rearrange small}, there is a positive number $p_2 = p_2 (d,n)$ such that
\begin{equation}\label{thm14 conc2}
\mathbf{P}_{\pi (\mathcal{C}_1)} \Big( U_{n} = \pi \big( \mathcal{A}_{\ref{alg2}} (\mathcal{C}_1) \big) \Big) \geq p_2.
\end{equation}
By Proposition \ref{alg2 works}, $\mathcal{C}_2$ equals $\mathcal{A}_{\ref{alg2}} (\mathcal{C}_1) = \mathcal{L} (\mathcal{C}_1)$. Since $\mathcal{C}_2$ is $n^2 a$ separated, by Proposition \ref{break lines}, there are positive  numbers $N_3 = N_3 (a,d,n)$ and $p_3 = p_3 (a,d,n)$ such that
\begin{equation}\label{thm14 conc3}
\mathbf{P}_{\pi (\mathcal{C}_2)} \Big( U_{N_3} = \pi \big( \mathcal{A}_{\ref{alg3}} (\mathcal{C}_2,a) \big) \Big) \geq p_3.
\end{equation}
Denote $\mathcal{C}_3 = \mathcal{A}_{\ref{alg3}} (\mathcal{C}_2,a)$. By the Markov property and \eqref{thm14 conc1} through \eqref{thm14 conc3},
\begin{equation}\label{thm14 conc4}
\mathbf{P}_U \big( U_{N_1+n+N_3} = \pi (\mathcal{C}_3) \big) \geq p_1 p_2 p_3.
\end{equation}
By Proposition \ref{alg3 works}, $\mathcal{C}_3 \in \mathrm{Clust}_{a,b}^\bullet \cap \mathrm{Ref}^\times$ with $b = 2 (\log a)^{-1}$. Note that $a \geq 4^d n$ (the constant in Lemma~\ref{lem hm comp}), so $b < 1$. Because $\mathcal{C}_3$ is $(a,b)$ separated for $b < 1$, it is also $(a,1)$ separated. Setting $N = N_1+n+N_3$ and $p = p_1 p_2 p_3$ concludes the proof.

